import {createRun,WORKFLOW_AGENTS} from './agents.js';
import {containsSecret} from './security.js';
const limits={topic:300,audience:300,goal:500,media:100,sources:20000,rules:15000,transcript:50000,metrics:10000};
export function validateSnapshot(value){if(!value||value.version!==1||!value.input||typeof value.input!=='object'||JSON.stringify(value).length>1500000||containsSecret(JSON.stringify(value)))throw new Error('保存した記事を読み取れませんでした。');const input={};for(const [k,max] of Object.entries(limits)){if(typeof value.input[k]!=='string'||value.input[k].length>max)throw new Error('保存した資料を読み取れませんでした。');input[k]=value.input[k];}if(!Number.isInteger(value.input.targetLength)||value.input.targetLength<300||value.input.targetLength>8000||typeof value.input.webSearch!=='boolean')throw new Error('企画の内容を確認してください。');input.targetLength=value.input.targetLength;input.webSearch=value.input.webSearch;input.editorialContext=null;if(!value.run)return {version:1,input,run:null};const original=value.run;if(!Array.isArray(original.agents)||original.agents.length!==WORKFLOW_AGENTS.length||!Number.isInteger(original.attempts)||original.attempts<0||original.attempts>48)throw new Error('制作記録を読み取れませんでした。');const run=createRun(input);run.id=String(original.id).slice(0,80);run.demo=original.demo===true;run.revision=Number.isInteger(original.revision)?original.revision:0;run.attempts=original.attempts;run.status=['awaiting_transcript','awaiting_metrics','awaiting_review','completed','task_completed','budget_exceeded','ready','failed','cancelled'].includes(original.status)?original.status:'ready';run.agents=WORKFLOW_AGENTS.map(a=>{const state=original.agents.find(s=>s.id===a.id);if(!state||JSON.stringify(state.output).length>120000)throw new Error('成果物を読み取れませんでした。');return {...state,id:a.id,status:['done','queued','awaiting','failed','cancelled'].includes(state.status)?state.status:'queued',error:typeof state.error==='string'?state.error.slice(0,500):''};});for(const key of ['reviewFindings','finalFindings','editorialChecks','usageRecords','audit'])run[key]=Array.isArray(original[key])?original[key].slice(-300):[];run.rejected=Number.isInteger(original.rejected)?original.rejected:0;run.reviewScope=original.reviewScope==='public'?'public':'draft';run.approvals={};return {version:1,input,run};}
export function snapshotForSave(input,run){return {version:1,input:structuredClone(input),run:run?structuredClone(run):null};}
export function paragraphEdit(article,index,replacement){const parts=article.split(/\n\s*\n/);if(!Number.isInteger(index)||index<0||index>=parts.length||typeof replacement!=='string'||!replacement.trim()||replacement.length>15000)throw new Error('変更する段落を確認してください。');parts[index]=replacement.trim();return parts.join('\n\n');}
export function lineDiff(before,after){const a=String(before).split('\n'),b=String(after).split('\n');return {before:a,after:b,changed:a.join('\n')!==b.join('\n')};}
